const canvas=...
const ctx=canvas.getContext('2d',{alpha:false});
const scoreEl=..., card=..., button=..., hint=..., footer=..., toast=..., toastText=..., ripple=...
const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;

const TAU=Math.PI*2;
const clamp=(v,a,b)=>...
const lerp=(a,b,t)=>a+(b-a)*t;
const easeOutCubic=t=>1-Math.pow(1-t,3)
const easeInCubic=t=>t*t*t
const easeInOutCubic...
const smooth...
function mulberry32(a){...}

let W,H,DPR,S,groundY,charX,stumpX,stumpTopY,pileX;
let bgCanvas=document.createElement('canvas'); let bgCtx;
let time=0,last=0;
let state = {score:0, logsShown:0, firstTap:true};

const IDLE={lean:.01, gripX:46, gripY:-140, angle:-1.2, bob:0, crouch:0};
const WIND={lean:-.16, gripX:2, gripY:-200, angle:-2.58, bob:-3, crouch:.15};
const STRIKE={lean:.21, gripX:33, gripY:-118, angle:.72, bob:3, crouch:.75};
