Mountain function:
```
function ridge(b, baseY, height, color, seed, alpha=1){
 const r=mulberry32(seed);
 b.beginPath(); b.moveTo(-20, baseY+40);
 let x=-20;
 while(x<W+30){ x+=W*(0.08+ r()*0.09); const y=baseY - height*(0.2+r()*0.8); b.lineTo(x,y); }
 b.lineTo(W+40, baseY+60); b.lineTo(-40,baseY+60); close; fill;
