Let's code character with details.

Character drawing functions:

```
function solveElbow(sx,sy,hx,hy,l1,l2){
  let dx=hx-sx, dy=hy-sy; let d=Math.hypot(dx,dy);
  const max=l1+l2-0.001; if(d>max){dx*=max/d;dy*=max/d;hx=sx+dx;hy=sy+dy;d=max;}
  d=Math.max(d,Math.abs(l1-l2)+.001);
  const a=(l1*l1-l2*l2+d*d)/(2*d);
  const h=Math.sqrt(Math.max(0,l1*l1-a*a));
  const mx=sx+dx*a/d, my=sy+dy*a/d;
  const p1={x:mx - dy*h/d, y:my + dx*h/d};
  const p2={x:mx + dy*h/d, y:my - dx*h/d};
  return p1.y>p2.y?p1:p2;
}
```

