function ridge(b, baseY, height, color, seed, opacity){
 const r=mulberry32(seed);
 b.save(); b.globalAlpha=opacity; b.fillStyle=color;
 b.beginPath(); b.moveTo(-40, baseY+60);
 let x=-40;
 while(x<W+80){
   const seg=W*(.10+r()*.10);
   const peak=baseY - height*(.25+r()*.75);
   const nx=x+seg;
   b.quadraticCurveTo(x+seg*.35, baseY-height*(.1+r()*.25), (x+nx)/2, peak);
   b.quadraticCurveTo(x+seg*.75, peak+height*.25, nx, baseY-height*(.1+r()*.35));
   x=nx;
 }
 b.lineTo(W+40, baseY+80); b.lineTo(-40,baseY+80); closePath(); fill; restore;
}
```
