  b.lineTo(x+half, bottom);
  b.lineTo(x+half*.55, ty+h*.18);
  b.lineTo(x+half*.72, ty+h*.145);
  b.lineTo(x+half*.35, ty+h*.10);
  closePath; fill;
 }
