/* Procedural golden-hour forest backdrop, rendered once per resize. */
import { TAU, mulberry32, ellipse, line, clamp } from './utils.js';

function drawCloud(b, x, y, size, color, alpha) {
  b.save();
  b.globalAlpha = alpha;
  b.fillStyle = color;
  b.filter = 'blur(11px)';
  b.beginPath();
  b.ellipse(x, y, size * 1.75, size * 0.30, -0.03, 0, TAU);
  b.ellipse(x - size * 0.7, y + size * 0.07, size * 0.85, size * 0.20, 0.05, 0, TAU);
  b.ellipse(x + size * 0.8, y - size * 0.04, size * 0.95, size * 0.18, -0.04, 0, TAU);
  b.fill();
  b.restore();
}

function drawRidge(b, W, baseY, height, color, seed, alpha) {
  const rand = mulberry32(seed);
  b.save();
  b.globalAlpha = alpha;
  b.fillStyle = color;
  b.beginPath();
  b.moveTo(-40, baseY + 80);
  let x = -40;
  while (x < W + 80) {
    const segment = W * (0.085 + rand() * 0.10);
    const peak = baseY - height * (0.25 + rand() * 0.75);
    const nx = x + segment;
    b.quadraticCurveTo(x + segment * 0.32, baseY - height * (0.1 + rand() * 0.22), (x + nx) / 2, peak);
    b.quadraticCurveTo(x + segment * 0.72, peak + height * (0.2 + rand() * 0.25), nx, baseY - height * (0.12 + rand() * 0.3));
    x = nx;
  }
  b.lineTo(W + 60, baseY + 90);
  b.lineTo(-40, baseY + 90);
  b.closePath();
  b.fill();
  b.restore();
}

function drawPine(b, x, baseY, h, w, color, alpha, seed) {
  const rand = mulberry32(seed);
  b.save();
  b.globalAlpha = alpha;
  b.fillStyle = color;

  b.fillRect(x - w * 0.025, baseY - h * 0.24, w * 0.05, h * 0.24);

  for (let i = 0; i < 5; i++) {
    const t = i / 5;
    const tipY = baseY - h + h * 0.125 * i;
    const half = w * (0.14 + t * 0.195);
    const foot = tipY + h * (0.30 - i * 0.015) + rand() * h * 0.012;
    b.beginPath();
    b.moveTo(x, tipY);
    b.lineTo(x - half * 0.34, tipY + h * 0.105);
    b.lineTo(x - half * 0.71, tipY + h * 0.138);
    b.lineTo(x - half * 0.52, tipY + h * 0.178);
    b.lineTo(x - half, foot);
    b.lineTo(x, foot - h * 0.018);
    b.lineTo(x + half, foot);
    b.lineTo(x + half * 0.52, tipY + h * 0.178);
    b.lineTo(x + half * 0.71, tipY + h * 0.138);
    b.lineTo(x + half * 0.34, tipY + h * 0.105);
    b.closePath();
    b.fill();
  }

  b.globalAlpha = alpha * 0.24;
  b.fillStyle = '#b8a46e';
  b.beginPath();
  b.moveTo(x, baseY - h + h * 0.02);
  b.lineTo(x + w * 0.15, baseY - h * 0.45);
  b.lineTo(x + w * 0.09, baseY - h * 0.44);
  b.closePath();
  b.fill();
  b.restore();
}

function drawForestBand(b, W, baseY, count, minH, maxH, color, alpha, seed, skipCenter) {
  const rand = mulberry32(seed);
  for (let i = 0; i < count; i++) {
    const x = ((i + 0.2 + rand() * 0.65) / count) * W;
    if (skipCenter && x > W * 0.25 && x < W * 0.82) continue;
    const h = (minH + rand() * (maxH - minH));
    const w = h * (0.26 + rand() * 0.10);
    drawPine(b, x, baseY + rand() * 14, h, w, color, alpha * (0.82 + rand() * 0.18), (rand() * 1e9) | 0);
  }
}

function drawCanopy(b, cx, cy, rx, ry, seed, litSide) {
  const rand = mulberry32(seed);
  const colors = ['#0b211d', '#102a24', '#14332b', '#183c30'];
  const count = 58;
  for (let i = 0; i < count; i++) {
    const angle = rand() * TAU;
    const radius = Math.sqrt(rand());
    const x = cx + Math.cos(angle) * rx * radius * 0.92;
    const y = cy + Math.sin(angle) * ry * radius * 0.78;
    const size = (13 + rand() * 27) * Math.min(1.3, Math.max(0.65, rx / 210));
    b.globalAlpha = 0.90;
    b.fillStyle = colors[(rand() * colors.length) | 0];
    b.beginPath();
    b.ellipse(x, y, size * (0.8 + rand() * 0.5), size * (0.6 + rand() * 0.4), rand() * TAU, 0, TAU);
    b.fill();
  }

  b.globalAlpha = 0.34;
  b.fillStyle = '#54704b';
  for (let i = 0; i < 18; i++) {
    const angle = rand() * TAU;
    const radius = Math.sqrt(rand()) * 0.82;
    const x = cx + Math.cos(angle) * rx * radius + litSide * rx * 0.18;
    const y = cy + Math.sin(angle) * ry * radius * 0.75 - ry * 0.08;
    const size = (8 + rand() * 16) * Math.min(1.25, Math.max(0.7, rx / 220));
    b.beginPath();
    b.ellipse(x, y, size, size * 0.66, rand() * TAU, 0, TAU);
    b.fill();
  }

  b.globalAlpha = 0.18;
  b.fillStyle = '#e4bd79';
  for (let i = 0; i < 22; i++) {
    const x = cx + (rand() - 0.5) * rx * 1.5 + litSide * rx * 0.25;
    const y = cy + (rand() - 0.5) * ry * 1.05;
    b.beginPath();
    b.arc(x, y, (1 + rand() * 2.2), 0, TAU);
    b.fill();
  }
  b.globalAlpha = 1;
}

function drawFramingTree(b, W, H, S, side, seed) {
  const rand = mulberry32(seed);
  const x = side < 0 ? W * 0.035 : W * 0.965;
  const base = H * 1.04;
  const height = H * (0.66 + rand() * 0.05);
  const width = clamp(40 * S, 30, 78);

  b.save();
  b.translate(x, base);
  b.rotate(side * 0.025);

  const trunk = b.createLinearGradient(-width * 0.65, 0, width * 0.65, 0);
  trunk.addColorStop(0, '#0a1915');
  trunk.addColorStop(0.52, '#152b23');
  trunk.addColorStop(1, '#081410');
  b.fillStyle = trunk;
  b.beginPath();
  b.moveTo(-width * 0.62, 0);
  b.bezierCurveTo(-width * 0.5, -height * 0.3, -width * 0.32, -height * 0.62, -width * 0.24, -height);
  b.lineTo(width * 0.24, -height);
  b.bezierCurveTo(width * 0.34, -height * 0.6, width * 0.52, -height * 0.28, width * 0.64, 0);
  b.closePath();
  b.fill();

  b.globalAlpha = 0.26;
  b.strokeStyle = '#4c5a42';
  b.lineWidth = 1.2;
  for (let i = 0; i < 16; i++) {
    const bx = (rand() - 0.5) * width * 0.8;
    b.beginPath();
    b.moveTo(bx, -height * (0.05 + rand() * 0.18));
    b.bezierCurveTo(bx + (rand() - 0.5) * 9, -height * 0.35, bx + (rand() - 0.5) * 12, -height * 0.58, bx + (rand() - 0.5) * 9, -height * (0.72 + rand() * 0.22));
    b.stroke();
  }

  b.globalAlpha = 0.38;
  b.strokeStyle = '#0a1713';
  b.lineWidth = clamp(9 * S, 5, 16);
  const branchY = -height * (0.53 + rand() * 0.07);
  b.beginPath();
  b.moveTo(0, branchY);
  b.quadraticCurveTo(side * -W * 0.07, branchY - H * 0.02, side * -W * 0.16, branchY - H * 0.075);
  b.stroke();
  b.restore();

  drawCanopy(
    b,
    side < 0 ? W * 0.075 : W * 0.925,
    H * 0.075,
    clamp(W * 0.20, 120, 300),
    clamp(H * 0.15, 105, 210),
    seed + 77,
    side < 0 ? 1 : -1
  );
}

export function renderBackground({ W, H, S, groundY, DPR }) {
  const canvas = document.createElement('canvas');
  canvas.width = Math.ceil(W * DPR);
  canvas.height = Math.ceil(H * DPR);
  const b = canvas.getContext('2d');
  b.setTransform(DPR, 0, 0, DPR, 0, 0);

  const rand = mulberry32(0x51f15e);
  const horizon = groundY - 26 * S;
  const sunX = W * 0.715;
  const sunY = horizon * 0.42;

  /* Sky */
  const sky = b.createLinearGradient(0, -H * 0.15, 0, horizon + 48 * S);
  sky.addColorStop(0, '#071b22');
  sky.addColorStop(0.20, '#103337');
  sky.addColorStop(0.43, '#28504c');
  sky.addColorStop(0.63, '#6c674e');
  sky.addColorStop(0.82, '#c78a55');
  sky.addColorStop(1, '#f2bc7a');
  b.fillStyle = sky;
  b.fillRect(0, 0, W, horizon + 70 * S);

  /* A few earliest stars */
  b.save();
  for (let i = 0; i < 26; i++) {
    const x = rand() * W;
    const y = rand() * H * 0.26;
    const a = (1 - y / (H * 0.3)) * (0.16 + rand() * 0.34);
    b.globalAlpha = Math.max(0, a);
    b.fillStyle = '#d8eadf';
    b.beginPath();
    b.arc(x, y, 0.55 + rand() * 0.9, 0, TAU);
    b.fill();
  }
  b.restore();

  /* Sun bloom and disc */
  b.save();
  b.globalCompositeOperation = 'screen';
  const bloom = b.createRadialGradient(sunX, sunY, 2, sunX, sunY, Math.max(W, H) * 0.54);
  bloom.addColorStop(0, 'rgba(255,239,190,.86)');
  bloom.addColorStop(0.07, 'rgba(255,214,133,.55)');
  bloom.addColorStop(0.24, 'rgba(244,166,88,.20)');
  bloom.addColorStop(0.55, 'rgba(224,134,68,.055)');
  bloom.addColorStop(1, 'rgba(224,134,68,0)');
  b.fillStyle = bloom;
  b.fillRect(0, 0, W, horizon + 90 * S);
  const disc = b.createRadialGradient(sunX, sunY, 0, sunX, sunY, 36 * S);
  disc.addColorStop(0, 'rgba(255,252,225,1)');
  disc.addColorStop(0.45, 'rgba(255,232,172,.98)');
  disc.addColorStop(0.78, 'rgba(255,207,126,.45)');
  disc.addColorStop(1, 'rgba(255,200,110,0)');
  b.fillStyle = disc;
  b.beginPath();
  b.arc(sunX, sunY, 36 * S, 0, TAU);
  b.fill();
  b.restore();

  /* Soft horizontal clouds */
  drawCloud(b, W * 0.22, horizon * 0.30, W * 0.12, '#40554d', 0.25);
  drawCloud(b, W * 0.62, horizon * 0.18, W * 0.16, '#344d47', 0.22);
  drawCloud(b, W * 0.85, horizon * 0.38, W * 0.13, '#7b6b4b', 0.22);
  drawCloud(b, W * 0.42, horizon * 0.52, W * 0.19, '#876d4b', 0.15);

  /* Birds */
  b.save();
  b.strokeStyle = 'rgba(16,36,32,.55)';
  b.lineWidth = 1.2;
  b.lineCap = 'round';
  for (let i = 0; i < 4; i++) {
    const bx = W * (0.16 + rand() * 0.26);
    const by = H * (0.12 + rand() * 0.10);
    const s = (4 + rand() * 5) * S;
    b.beginPath();
    b.moveTo(bx - s, by);
    b.quadraticCurveTo(bx - s * 0.4, by - s * 0.55, bx, by);
    b.quadraticCurveTo(bx + s * 0.4, by - s * 0.55, bx + s, by);
    b.stroke();
  }
  b.restore();

  /* Layered mountains */
  drawRidge(b, W, horizon + 12 * S, 128 * S, '#45605a', 0x8123, 0.38);
  drawRidge(b, W, horizon + 22 * S, 88 * S, '#2f4b46', 0x9284, 0.65);
  drawRidge(b, W, horizon + 30 * S, 56 * S, '#213e39', 0x1377, 0.8);

  /* Haze at the base of the mountains */
  const haze = b.createLinearGradient(0, horizon - 44 * S, 0, horizon + 52 * S);
  haze.addColorStop(0, 'rgba(249,197,128,0)');
  haze.addColorStop(0.55, 'rgba(240,185,120,.16)');
  haze.addColorStop(1, 'rgba(233,175,112,.03)');
  b.fillStyle = haze;
  b.fillRect(0, horizon - 50 * S, W, 105 * S);

  /* Ground plane */
  const earth = b.createLinearGradient(0, horizon, 0, H);
  earth.addColorStop(0, '#586238');
  earth.addColorStop(0.18, '#48522f');
  earth.addColorStop(0.46, '#343f27');
  earth.addColorStop(0.75, '#263322');
  earth.addColorStop(1, '#16231b');
  b.fillStyle = earth;
  b.fillRect(0, horizon, W, H - horizon);

  const hillLight = b.createRadialGradient(W * 0.62, groundY + 20 * S, 10, W * 0.62, groundY + 20 * S, W * 0.72);
  hillLight.addColorStop(0, 'rgba(214,169,100,.16)');
  hillLight.addColorStop(0.55, 'rgba(172,138,78,.06)');
  hillLight.addColorStop(1, 'rgba(86,94,52,0)');
  b.fillStyle = hillLight;
  b.fillRect(0, horizon, W, H - horizon);

  /* Distant tree lines */
  drawForestBand(b, W, horizon + 14 * S, 62, 22 * S, 68 * S, '#27453d', 0.50, 0x1021, false);
  drawForestBand(b, W, horizon + 24 * S, 34, 42 * S, 112 * S, '#1d3933', 0.68, 0x2202, false);
  drawForestBand(b, W, horizon + 40 * S, 19, 85 * S, 176 * S, '#162f2a', 0.86, 0x3313, true);
  drawForestBand(b, W, horizon + 66 * S, 9, 150 * S, 270 * S, '#102821', 0.94, 0x4414, true);

  /* Dirt clearing at the chopping spot */
  b.save();
  b.translate(W * 0.54, groundY + 9 * S);
  b.scale(1, 0.27);
  const dirt = b.createRadialGradient(0, 0, 12, 0, 0, Math.max(W * 0.36, 165 * S));
  dirt.addColorStop(0, 'rgba(151,113,67,.52)');
  dirt.addColorStop(0.5, 'rgba(130,96,57,.32)');
  dirt.addColorStop(0.82, 'rgba(101,79,48,.12)');
  dirt.addColorStop(1, 'rgba(84,70,44,0)');
  b.fillStyle = dirt;
  b.beginPath();
  b.arc(0, 0, Math.max(W * 0.36, 165 * S), 0, TAU);
  b.fill();
  b.restore();

  /* Grass blades */
  const grassPalette = [
    ['#7c8348', 0.34],
    ['#67763d', 0.42],
    ['#586b34', 0.50],
    ['#455c2d', 0.6],
    ['#334b27', 0.7],
  ];
  for (let i = 0; i < 390; i++) {
    const depth = Math.pow(rand(), 0.72);
    const y = horizon + 6 * S + depth * (H - horizon + 8 * S);
    const x = rand() * W;
    const size = (0.32 + depth * 1.35);
    const length = (5 + rand() * 14) * size * S;
    const lean = (rand() - 0.5) * length * 0.46;
    const palette = grassPalette[Math.min(grassPalette.length - 1, Math.floor(depth * 4.2))];
    b.globalAlpha = palette[1] * (0.55 + rand() * 0.45);
    b.strokeStyle = palette[0];
    b.lineWidth = Math.max(0.7, size * 1.2);
    b.lineCap = 'round';
    b.beginPath();
    b.moveTo(x, y);
    b.quadraticCurveTo(x + lean * 0.3, y - length * 0.58, x + lean, y - length);
    b.stroke();
    if (rand() > 0.62) {
      b.beginPath();
      b.moveTo(x + size * 1.8, y);
      b.quadraticCurveTo(x + lean * 0.16 + size * 1.4, y - length * 0.45, x + lean * 0.4 + size * 2.4, y - length * 0.82);
      b.stroke();
    }
  }
  b.globalAlpha = 1;

  /* Fallen leaves and small stones */
  const leafColors = ['#b86932', '#c98039', '#9e5029', '#d1964e', '#7b4a2b'];
  for (let i = 0; i < 95; i++) {
    const depth = Math.pow(rand(), 0.45);
    const x = rand() * W;
    const y = horizon + 28 * S + depth * (H - horizon - 5 * S);
    const size = (1.8 + rand() * 3.4) * (0.7 + depth * 0.8) * S;
    b.save();
    b.translate(x, y);
    b.rotate(rand() * TAU);
    b.globalAlpha = 0.22 + rand() * 0.34;
    b.fillStyle = leafColors[(rand() * leafColors.length) | 0];
    b.beginPath();
    b.ellipse(0, 0, size, size * 0.42, 0, 0, TAU);
    b.fill();
    b.restore();
  }

  for (let i = 0; i < 13; i++) {
    const depth = rand();
    const x = rand() * W;
    const y = horizon + 40 * S + depth * (H - horizon - 30 * S);
    const size = (2 + rand() * 7) * (0.5 + depth) * S;
    b.globalAlpha = 0.24 + depth * 0.3;
    b.fillStyle = '#5b5c4b';
    b.beginPath();
    b.ellipse(x, y, size, size * 0.62, rand() * 0.5, 0, TAU);
    b.fill();
    b.globalAlpha = 0.10 + depth * 0.16;
    b.fillStyle = '#d8c08b';
    b.beginPath();
    b.ellipse(x - size * 0.25, y - size * 0.2, size * 0.55, size * 0.27, rand() * 0.5, 0, TAU);
    b.fill();
  }
  b.globalAlpha = 1;

  /* Tiny meadow flowers */
  for (let i = 0; i < 23; i++) {
    const x = rand() * W;
    const y = horizon + 45 * S + Math.pow(rand(), 0.65) * (H - horizon - 40 * S);
    const depth = (y - horizon) / (H - horizon);
    b.globalAlpha = 0.24 + depth * 0.4;
    b.fillStyle = rand() > 0.45 ? '#ddc47f' : '#d8e0c2';
    b.beginPath();
    b.arc(x, y, (0.9 + rand() * 1.3) * (0.6 + depth) * S, 0, TAU);
    b.fill();
  }
  b.globalAlpha = 1;

  /* Warm god rays */
  b.save();
  b.globalCompositeOperation = 'screen';
  b.translate(sunX, sunY);
  const rayAngles = [1.83, 1.98, 2.12, 2.28, 2.45, 2.61];
  for (let i = 0; i < rayAngles.length; i++) {
    b.save();
    b.rotate(rayAngles[i]);
    const length = Math.max(W, H) * 1.18;
    const ray = b.createLinearGradient(0, 0, length, 0);
    ray.addColorStop(0, `rgba(255,232,173,${0.15 + (i % 2) * 0.035})`);
    ray.addColorStop(0.35, 'rgba(255,216,144,.055)');
    ray.addColorStop(0.8, 'rgba(255,205,130,.012)');
    ray.addColorStop(1, 'rgba(255,205,130,0)');
    b.fillStyle = ray;
    b.beginPath();
    b.moveTo(0, -4 - i);
    b.lineTo(length, -105 + i * 18);
    b.lineTo(length, 105 - i * 9);
    b.lineTo(0, 4 + i);
    b.closePath();
    b.fill();
    b.restore();
  }
  b.restore();

  /* Foreground framing trees and canopy */
  drawFramingTree(b, W, H, S, -1, 0x9911);
  drawFramingTree(b, W, H, S, 1, 0xab22);

  /* Soft foreground vignette flakes of out-of-focus foliage */
  b.save();
  const fg = b.createLinearGradient(0, H * 0.72, 0, H);
  fg.addColorStop(0, 'rgba(8,21,16,0)');
  fg.addColorStop(1, 'rgba(7,17,14,.45)');
  b.fillStyle = fg;
  b.fillRect(0, H * 0.72, W, H * 0.28);
  b.restore();

  return canvas;
}

/* Small reusable line helper kept local to avoid importing it unused elsewhere. */
export { line };

/* Stump, firewood and the growing pile beside the chopping block. */
import { TAU, roundRect } from './utils.js';

export function logSlot(L, index) {
  const S = L.S;
  const row = Math.floor(index / 4);
  const col = index % 4;
  const w = 50 * S;
  const h = 14.5 * S;
  const x = L.pileX - 29 * S + col * 18.5 * S + (row % 2) * 7 * S;
  const y = L.groundY - 8.5 * S - row * 13.5 * S - (col % 2) * 1.7 * S;
  const rot = (col % 2 ? -0.035 : 0.038) + (row % 2 ? -0.018 : 0.015);
  return { x, y, w, h, rot };
}

export function drawLog(ctx, x, y, w, h, rot = 0, alpha = 1) {
  const radius = h * 0.5;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rot);
  ctx.globalAlpha = alpha;

  const body = ctx.createLinearGradient(0, -h * 0.55, 0, h * 0.55);
  body.addColorStop(0, '#8e5d32');
  body.addColorStop(0.28, '#724a28');
  body.addColorStop(0.72, '#5c3a1f');
  body.addColorStop(1, '#3f2715');
  ctx.fillStyle = body;
  roundRect(ctx, -w / 2, -h / 2, w, h, radius);
  ctx.fill();

  ctx.globalAlpha = alpha * 0.55;
  ctx.fillStyle = '#c18a52';
  roundRect(ctx, -w / 2 + h * 0.25, -h / 2 + h * 0.16, w * 0.6, h * 0.22, h * 0.12);
  ctx.fill();

  ctx.globalAlpha = alpha * 0.42;
  ctx.strokeStyle = '#351f10';
  ctx.lineWidth = Math.max(0.7, h * 0.055);
  ctx.lineCap = 'round';
  for (let i = 0; i < 3; i++) {
    const yy = (i - 1) * h * 0.22;
    ctx.beginPath();
    ctx.moveTo(-w * 0.32 + i * 2, yy);
    ctx.quadraticCurveTo(0, yy + h * 0.03, w * 0.28, yy);
    ctx.stroke();
  }

  /* Visible cut face at the right end */
  const ex = w / 2 - h * 0.16;
  ctx.globalAlpha = alpha;
  const face = ctx.createRadialGradient(ex - h * 0.12, -h * 0.12, 0, ex, 0, h * 0.62);
  face.addColorStop(0, '#f0c88e');
  face.addColorStop(0.55, '#d2a067');
  face.addColorStop(1, '#9d6a3b');
  ctx.fillStyle = face;
  ctx.beginPath();
  ctx.ellipse(ex, 0, h * 0.48, h * 0.48, 0, 0, TAU);
  ctx.fill();

  ctx.globalAlpha = alpha * 0.5;
  ctx.strokeStyle = '#8d5a30';
  ctx.lineWidth = Math.max(0.6, h * 0.04);
  for (let r = 0.15; r < 0.44; r += 0.105) {
    ctx.beginPath();
    ctx.ellipse(ex, 0, h * r, h * r * 0.92, 0.2, 0, TAU);
    ctx.stroke();
  }
  ctx.globalAlpha = alpha * 0.6;
  ctx.strokeStyle = '#6d4525';
  ctx.beginPath();
  ctx.moveTo(ex - h * 0.1, -h * 0.15);
  ctx.lineTo(ex + h * 0.08, h * 0.02);
  ctx.stroke();
  ctx.restore();
}

export function drawLogPile(ctx, L, count) {
  const visible = Math.min(count, 28);
  if (visible <= 0) return;

  ctx.save();
  const shadow = ctx.createRadialGradient(L.pileX, L.groundY - 2 * L.S, 2, L.pileX, L.groundY - 2 * L.S, 68 * L.S);
  shadow.addColorStop(0, 'rgba(8,14,10,.36)');
  shadow.addColorStop(1, 'rgba(8,14,10,0)');
  ctx.fillStyle = shadow;
  ctx.save();
  ctx.translate(L.pileX, L.groundY);
  ctx.scale(1, 0.28);
  ctx.beginPath();
  ctx.arc(0, 0, 68 * L.S, 0, TAU);
  ctx.fill();
  ctx.restore();

  for (let i = 0; i < visible; i++) {
    const slot = logSlot(L, i);
    drawLog(ctx, slot.x, slot.y, slot.w, slot.h, slot.rot, 1);
  }
  ctx.restore();
}

export function drawFlyLog(ctx, from, to, progress, L, index) {
  const t = Math.min(1, Math.max(0, progress));
  const ease = 1 - Math.pow(1 - t, 3);
  const x = from.x + (to.x - from.x) * ease;
  const arc = Math.sin(Math.PI * t) * 62 * L.S;
  const y = from.y + (to.y - from.y) * ease - arc;
  const rot = from.rot + (to.rot - from.rot) * ease + Math.sin(Math.PI * t) * 0.9;
  drawLog(ctx, x, y, to.w, to.h, rot, 1);
}

export function drawStump(ctx, L, score, time) {
  const S = L.S;
  const cx = L.stumpX;
  const topY = L.stumpTopY;
  const ground = L.groundY;
  const rx = 47 * S;
  const ry = 12.5 * S;
  const h = ground - topY;

  /* Contact shadow */
  ctx.save();
  ctx.translate(cx, ground + 1 * S);
  ctx.scale(1, 0.26);
  const shadow = ctx.createRadialGradient(0, 0, 2, 0, 0, rx * 1.55);
  shadow.addColorStop(0, 'rgba(6,12,8,.48)');
  shadow.addColorStop(0.65, 'rgba(6,12,8,.20)');
  shadow.addColorStop(1, 'rgba(6,12,8,0)');
  ctx.fillStyle = shadow;
  ctx.beginPath();
  ctx.arc(0, 0, rx * 1.55, 0, TAU);
  ctx.fill();
  ctx.restore();

  /* Bark body */
  const bark = ctx.createLinearGradient(cx - rx, 0, cx + rx, 0);
  bark.addColorStop(0, '#3b2919');
  bark.addColorStop(0.24, '#684929');
  bark.addColorStop(0.55, '#7d5732');
  bark.addColorStop(0.82, '#563b22');
  bark.addColorStop(1, '#332216');
  ctx.fillStyle = bark;
  ctx.beginPath();
  ctx.moveTo(cx - rx, topY + ry * 0.1);
  ctx.bezierCurveTo(cx - rx - 3 * S, topY + h * 0.35, cx - rx + 2 * S, topY + h * 0.7, cx - rx + 3 * S, ground + 2 * S);
  ctx.quadraticCurveTo(cx - rx * 0.4, ground + 9 * S, cx + rx * 0.32, ground + 4 * S);
  ctx.bezierCurveTo(cx + rx * 0.85, ground + 1 * S, cx + rx - 1 * S, topY + h * 0.68, cx + rx + 2 * S, topY + h * 0.3);
  ctx.lineTo(cx + rx, topY + ry * 0.1);
  ctx.closePath();
  ctx.fill();

  /* Bark grooves */
  ctx.globalAlpha = 0.36;
  ctx.strokeStyle = '#2e1d11';
  ctx.lineWidth = 1.35 * S;
  ctx.lineCap = 'round';
  for (let i = 0; i < 13; i++) {
    const bx = cx - rx * 0.85 + (i / 12) * rx * 1.7;
    const sway = Math.sin(i * 2.1) * 2.4 * S;
    ctx.beginPath();
    ctx.moveTo(bx, topY + ry + (i % 3) * 3 * S);
    ctx.bezierCurveTo(bx + sway, topY + h * 0.35, bx - sway, topY + h * 0.68, bx + sway * 0.5, ground - 4 * S);
    ctx.stroke();
  }
  ctx.globalAlpha = 0.22;
  ctx.strokeStyle = '#c08d53';
  for (let i = 0; i < 5; i++) {
    const bx = cx - rx * 0.65 + i * rx * 0.3;
    ctx.beginPath();
    ctx.moveTo(bx, topY + ry + 4 * S);
    ctx.quadraticCurveTo(bx + 2 * S, topY + h * 0.45, bx, ground - 6 * S);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  /* Moss at the foot */
  const moss = ctx.createRadialGradient(cx - rx * 0.5, ground - 7 * S, 1, cx - rx * 0.35, ground - 5 * S, 32 * S);
  moss.addColorStop(0, 'rgba(94,116,53,.5)');
  moss.addColorStop(1, 'rgba(58,82,38,0)');
  ctx.fillStyle = moss;
  ctx.beginPath();
  ctx.ellipse(cx - rx * 0.35, ground - 5 * S, 31 * S, 11 * S, -0.08, 0, TAU);
  ctx.fill();

  /* Cut surface */
  const top = ctx.createRadialGradient(cx - rx * 0.22, topY - ry * 0.25, 1, cx, topY, rx * 1.04);
  top.addColorStop(0, '#e2b77b');
  top.addColorStop(0.42, '#cfa169');
  top.addColorStop(0.8, '#a87845');
  top.addColorStop(1, '#7e5731');
  ctx.fillStyle = top;
  ctx.beginPath();
  ctx.ellipse(cx, topY, rx, ry, 0, 0, TAU);
  ctx.fill();

  /* Growth rings */
  ctx.save();
  ctx.globalAlpha = 0.38;
  ctx.strokeStyle = '#8f6338';
  ctx.lineWidth = 1.1 * S;
  for (let i = 0; i < 5; i++) {
    const r = 0.2 + i * 0.145;
    ctx.beginPath();
    ctx.ellipse(cx - rx * 0.03, topY, rx * r, ry * r, 0.02, 0, TAU);
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.moveTo(cx - rx * 0.07, topY - ry * 0.2);
  ctx.quadraticCurveTo(cx + rx * 0.03, topY + ry * 0.1, cx - rx * 0.01, topY + ry * 0.34);
  ctx.stroke();
  ctx.restore();

  /* Chopped notch on the near-left edge */
  ctx.fillStyle = '#3b2716';
  ctx.beginPath();
  ctx.moveTo(cx - rx + 1 * S, topY - ry * 0.1);
  ctx.lineTo(cx - rx * 0.34, topY + ry * 0.25);
  ctx.lineTo(cx - rx + 2 * S, topY + ry * 0.95);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(238,199,139,.35)';
  ctx.lineWidth = 1.2 * S;
  ctx.beginPath();
  ctx.moveTo(cx - rx + 1 * S, topY - ry * 0.1);
  ctx.lineTo(cx - rx * 0.34, topY + ry * 0.25);
  ctx.stroke();

  /* Fresh cut marks grow with the score */
  const marks = Math.min(score, 7);
  ctx.save();
  ctx.globalAlpha = 0.5;
  ctx.strokeStyle = '#f1d19a';
  ctx.lineWidth = 1.4 * S;
  for (let i = 0; i < marks; i++) {
    const mx = cx + rx * (0.05 + i * 0.095);
    const my = topY - ry * 0.5 + (i % 2) * ry * 0.22;
    ctx.beginPath();
    ctx.moveTo(mx, my);
    ctx.lineTo(mx + 6 * S, my + 2.4 * S);
    ctx.stroke();
  }
  ctx.restore();

  /* A tiny fern beside the stump */
  ctx.save();
  ctx.globalAlpha = 0.7;
  ctx.strokeStyle = '#536c38';
  ctx.lineWidth = 1.3 * S;
  for (let i = 0; i < 4; i++) {
    const a = -0.85 - i * 0.18;
    const len = (14 + i * 4) * S;
    const fx = cx + rx * 0.72;
    const fy = ground - 2 * S;
    ctx.beginPath();
    ctx.moveTo(fx, fy);
    ctx.quadraticCurveTo(fx + Math.cos(a) * len * 0.5, fy + Math.sin(a) * len * 0.6, fx + Math.cos(a) * len, fy + Math.sin(a) * len);
    ctx.stroke();
  }
  ctx.restore();
}

/* Procedural lumberjack rig: legs, torso, head, arms and the axe. */
import { TAU, clamp, solveElbow, roundRect, line } from './utils.js';

const HIP_Y = -104;

function torsoPath(ctx) {
  ctx.beginPath();
  ctx.moveTo(-19, -101);
  ctx.bezierCurveTo(-31, -124, -29, -160, -18, -180);
  ctx.bezierCurveTo(-11, -192, 1, -198, 17, -198);
  ctx.bezierCurveTo(32, -198, 43, -191, 45, -175);
  ctx.lineTo(36, -104);
  ctx.bezierCurveTo(18, -95, -2, -95, -19, -101);
  ctx.closePath();
}

function axeFrame(pose) {
  const c = Math.cos(pose.angle);
  const s = Math.sin(pose.angle);
  return {
    cos: c,
    sin: s,
    backHand: { x: pose.gripX - c * 15, y: pose.gripY - s * 15 },
    frontHand: { x: pose.gripX + c * 13, y: pose.gripY + s * 13 },
    head: { x: pose.gripX + c * 99, y: pose.gripY + s * 99 },
    tip: { x: pose.gripX + c * 118, y: pose.gripY + s * 118 },
  };
}

function drawBoot(ctx, x, y, front) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(front ? -0.03 : 0.05);
  if (!front) ctx.scale(0.9, 0.92);
  ctx.beginPath();
  ctx.moveTo(-10, -9);
  ctx.quadraticCurveTo(2, -11, 12, -8);
  ctx.quadraticCurveTo(22, -6, 25, 0);
  ctx.quadraticCurveTo(25, 4, 18, 4.5);
  ctx.lineTo(-9, 4.5);
  ctx.quadraticCurveTo(-13, 3, -13, -2);
  ctx.closePath();
  ctx.fillStyle = front ? '#4d2d19' : '#3a2114';
  ctx.fill();
  ctx.strokeStyle = '#2a160c';
  ctx.lineWidth = 1.7;
  ctx.stroke();

  ctx.strokeStyle = '#7b4a2b';
  ctx.lineWidth = 1.5;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-6, -8);
  ctx.quadraticCurveTo(3, -9.4, 12, -7);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(3, -7);
  ctx.lineTo(11, -6);
  ctx.moveTo(1, -3);
  ctx.lineTo(11, -2);
  ctx.stroke();

  ctx.fillStyle = '#21130b';
  roundRect(ctx, -13, 2.2, 38, 3.2, 1.6);
  ctx.fill();
  ctx.restore();
}

function drawLeg(ctx, hip, knee, ankle, front) {
  const outline = '#1e241c';
  const cloth = front ? '#3d4939' : '#313b2f';

  line(ctx, hip.x, hip.y, knee.x, knee.y, front ? 23 : 21, outline);
  line(ctx, hip.x, hip.y, knee.x, knee.y, front ? 18.5 : 16.5, cloth);

  ctx.globalAlpha = 0.28;
  line(ctx, hip.x + 4, hip.y - 3, knee.x + 2, knee.y + 4, 2.2, '#a5a181');
  ctx.globalAlpha = 1;

  line(ctx, knee.x, knee.y, ankle.x, ankle.y, front ? 21 : 19, outline);
  line(ctx, knee.x, knee.y, ankle.x, ankle.y, front ? 16.5 : 14.5, front ? '#35402f' : '#2a3428');

  /* rolled cuff */
  const cx = ankle.x + (knee.x - ankle.x) * 0.16;
  const cy = ankle.y + (knee.y - ankle.y) * 0.16;
  const a = Math.atan2(knee.y - ankle.y, knee.x - ankle.x);
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(a);
  ctx.strokeStyle = '#263026';
  ctx.lineWidth = front ? 17 : 15;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-4, 0);
  ctx.lineTo(4, 0);
  ctx.stroke();
  ctx.strokeStyle = '#596149';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-4, -6);
  ctx.lineTo(-4, 6);
  ctx.stroke();
  ctx.restore();

  drawBoot(ctx, ankle.x + (front ? 3 : 0), -1, front);
}

function drawArm(ctx, shoulder, hand, front) {
  const elbow = solveElbow(shoulder.x, shoulder.y, hand.x, hand.y, 39, 41);
  const outline = front ? '#4a1c13' : '#361711';
  const sleeve = front ? '#a93e29' : '#7f2b1e';

  line(ctx, shoulder.x, shoulder.y, elbow.x, elbow.y, front ? 21 : 18, outline);
  line(ctx, shoulder.x, shoulder.y, elbow.x, elbow.y, front ? 17 : 14.5, sleeve);

  ctx.globalAlpha = front ? 0.28 : 0.15;
  line(ctx, shoulder.x - 2, shoulder.y - 1, elbow.x - 2, elbow.y, 3.2, '#ffb98b');
  ctx.globalAlpha = 1;

  /* Plaid bands on the upper sleeve */
  ctx.save();
  ctx.translate(shoulder.x, shoulder.y);
  ctx.rotate(Math.atan2(elbow.y - shoulder.y, elbow.x - shoulder.x));
  ctx.globalAlpha = 0.24;
  ctx.strokeStyle = '#40130d';
  ctx.lineWidth = 2.2;
  const armLength = Math.hypot(elbow.x - shoulder.x, elbow.y - shoulder.y);
  ctx.beginPath();
  ctx.moveTo(armLength * 0.42, -8);
  ctx.lineTo(armLength * 0.42, 8);
  ctx.moveTo(armLength * 0.67, -8);
  ctx.lineTo(armLength * 0.67, 8);
  ctx.stroke();
  ctx.restore();

  /* Cuff */
  const cuffX = elbow.x + (hand.x - elbow.x) * 0.14;
  const cuffY = elbow.y + (hand.y - elbow.y) * 0.14;
  const angle = Math.atan2(hand.y - elbow.y, hand.x - elbow.x);
  ctx.save();
  ctx.translate(cuffX, cuffY);
  ctx.rotate(angle);
  ctx.strokeStyle = front ? '#7d2a1d' : '#5b2017';
  ctx.lineWidth = front ? 15 : 12.5;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-2.5, 0);
  ctx.lineTo(2.5, 0);
  ctx.stroke();
  ctx.strokeStyle = '#d38d63';
  ctx.lineWidth = front ? 5.6 : 4.6;
  ctx.beginPath();
  ctx.moveTo(3.2, 0);
  ctx.lineTo(10, 0);
  ctx.stroke();
  ctx.restore();

  line(ctx, elbow.x, elbow.y, hand.x, hand.y, front ? 12.5 : 10.5, '#2f180d');
  line(ctx, elbow.x, elbow.y, hand.x, hand.y, front ? 9.5 : 7.8, front ? '#ca8b5d' : '#a66c45');
  ctx.globalAlpha = 0.35;
  line(ctx, elbow.x + 1, elbow.y, hand.x, hand.y, 1.6, '#f0bd8d');
  ctx.globalAlpha = 1;

  return elbow;
}

function drawGlove(ctx, x, y, angle, front) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.fillStyle = front ? '#5b3520' : '#482a19';
  ctx.strokeStyle = '#2d180c';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.ellipse(0, 0, 7.2, 6.2, 0, 0, TAU);
  ctx.fill();
  ctx.stroke();

  ctx.fillStyle = '#7b4a2c';
  roundRect(ctx, -9, -5, 3.2, 10, 1.6);
  ctx.fill();

  ctx.fillStyle = front ? '#6a3e25' : '#56311d';
  ctx.beginPath();
  ctx.ellipse(3.6, 2.7, 3.1, 2.2, -0.4, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawHead(ctx) {
  const cx = 17;
