  /* nose */
  ctx.fillStyle = '#d99765';
  ctx.beginPath();
  ctx.moveTo(36.5, -228);
  ctx.quadraticCurveTo(43, -222, 41.6, -217.4);
  ctx.quadraticCurveTo(40.5, -214.4, 35.5, -215.4);
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 0.3;
  ctx.fillStyle = '#f4c79b';
  ctx.beginPath();
  ctx.ellipse(38.7, -224, 1.8, 3.6, 0.4, 0, TAU);
  ctx.fill();
  ctx.globalAlpha = 1;

  /* cheek */
  ctx.globalAlpha = 0.17;
  ctx.fillStyle = '#ffd5a2';
  ctx.beginPath();
