  ctx.fillStyle = 'rgba(255,245,220,.85)';
  ctx.beginPath();
  ctx.arc(29.7, -228.4, 0.7, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#57371f';
  ctx.lineWidth = 1.9;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(23.5, -234.2);
  ctx.quadraticCurveTo(29, -236.2, 34.5, -233.5);
