  for (let i = 0; i < 4; i++) {
    const t = i / 3;
    const bx = -8 + t * 7;
    const by = -5 + t * 4.3;
    ctx.beginPath();
    ctx.moveTo(bx, by);
    ctx.lineTo(bx - 3.2, by - 1.7);
    ctx.moveTo(bx, by);
    ctx.lineTo(bx - 2.2, by + 2);
