      vx: (rand() - 0.5) * 18 * L.S,
      sway: (8 + rand() * 18) * L.S,
      freq: 0.5 + rand() * 1.4,
      phase: rand() * TAU,
      rot: rand() * TAU,
      vr: (rand() - 0.5) * 2.5,
      size: (2.8 + rand() * 4.2) * L.S,
      z: rand(),
      color: ['#d07a34', '#bb5f2c', '#dfa14b', '#9d4c27', '#c99245'][Math.floor(rand() * 5)],
    });
  }

  motes = [];
  for (let i = 0; i < 42; i++) {
    motes.push({
      x: rand() * L.W,
      y: L.groundY - rand() * L.H * 0.62,
      vy: (1.5 + rand() * 6) * L.S,
      sway: (2 + rand() * 8) * L.S,
      freq: 0.25 + rand() * 0.9,
      phase: rand() * TAU,
      size: (0.6 + rand() * 1.8) * L.S,
      alpha: 0.12 + rand() * 0.4,
    });
  }

  fireflies = [];
  for (let i = 0; i < 15; i++) {
    fireflies.push({
      x: rand() * L.W,
      y: L.groundY - rand() * 85 * L.S,
      phase: rand() * TAU,
      freq: 0.55 + rand() * 1.2,
      drift: (2 + rand() * 5) * L.S,
      size: (0.9 + rand() * 1.4) * L.S,
    });
  }
}

function updateAmbient(dt) {
  const time = state.time;
  for (const l of leaves) {
    l.x += (l.vx + Math.sin(time * l.freq + l.phase) * l.sway) * dt;
    l.y += l.vy * dt;
